const ALERT_KEY='candex-quality-alerts';
const qualityAlerts={
 items:(()=>{try{const v=JSON.parse(localStorage.getItem(ALERT_KEY)||'[]');return Array.isArray(v)?v:[];}catch{return [];}})(),
 save(){try{localStorage.setItem(ALERT_KEY,JSON.stringify(this.items));}catch{}},
 find(code,metricId){return this.items.find(a=>a.code===code&&a.metricId===metricId);},
 open(){return this.items.filter(a=>a.status==='open');},
 forRegion(region){return this.items.filter(a=>a.region===region);},
 isResolved(){return false;},
 add(a){const ex=this.find(a.code,a.metricId);if(ex){if(ex.status==='open'||this.isResolved(ex))return null;Object.assign(ex,a,{status:'open',sentAt:new Date().toISOString()});delete ex.ackAt;this.save();return ex;}const item={...a,id:`${a.code}-${a.metricId}`,status:'open',sentAt:new Date().toISOString()};this.items.push(item);this.save();return item;},
 acknowledge(id){const a=this.items.find(a=>a.id===id);if(a&&a.status==='open'){a.status='acknowledged';a.ackAt=new Date().toISOString();this.save();}return a;}
};
