const pageArtFor=()=>pageArt[state.view==='overview'?`${state.role}-overview`:state.view]||'';
function heading(title,sub,eyebrow='',extra=''){const art=pageArtFor();const svg=art?`<svg class="page-art" viewBox="0 0 260 140" aria-hidden="true" focusable="false"><circle class="blob" cx="172" cy="70" r="66"/>${art}</svg>`:'';return `<div class="page-heading${art?' has-art':''}"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1 tabindex="-1" id="page-title">${title}</h1><p>${sub}</p></div>${svg||extra?`<div class="heading-side">${svg}${extra}</div>`:''}</div>`;}
// This gate organises the fictional hackathon Dashboards. It is not authentication.
const demoAccess=window.CandexDemoAccess||{current:()=>null,validRole:()=>false,allows:()=>false,enter(){throw new Error('Demo entry could not load. Refresh the page.');},leave(){}};
let entryOpen=true,entryRole=null,entryAbout=false,entryReturn=null,dicomModule=null,hadWorkspace=false;
function getRoute(){
 const raw=location.hash.replace(/^#/, '');
 if(raw==='main')return;
 if(raw==='about'){entryOpen=true;entryAbout=true;return;}
 const parts=raw.match(/^(patient|care|quality)\/([a-z-]+)$/);
 const role=parts?.[1],view=parts?.[2],session=demoAccess.current();
 if(!parts||!session||session.role!==role){
  entryOpen=true;entryAbout=false;
  if(role){entryRole=role;entryReturn=demoAccess.allows(role,view)?`${role}/${view}`:null;}
  else {entryRole=null;entryReturn=null;}
  return;
 }
 entryOpen=false;entryAbout=false;state.role=session.role;
 state.view=Object.hasOwn(viewTitles,view)&&demoAccess.allows(role,view)?view:'overview';
}
function resetWorkspaceSession(){
 window.candexAgent?.resetSession?.();
 dicomModule?.resetDicomSession?.();
 pendingRecordId=null;
}
function leaveDemo(){
 demoAccess.leave();resetWorkspaceSession();
 entryOpen=true;entryRole=null;entryAbout=false;entryReturn=null;
 if($('#dialog')?.open)$('#dialog').close();
 if(typeof history!=='undefined'&&history.replaceState)history.replaceState(null,'','#welcome');else location.hash='#welcome';
 render(true);
}
function enterDemo(role){
 const next=entryReturn?.startsWith(`${role}/`)?entryReturn:`${role}/overview`;
 demoAccess.enter(role);entryOpen=false;entryAbout=false;entryReturn=null;
 state.role=role;state.view=next.split('/')[1];
 if(typeof history!=='undefined'&&history.replaceState)history.replaceState(null,'',`#${next}`);else location.hash=`#${next}`;
 getRoute();render(true);
}
function entryView(){
 if(entryAbout)return `<main id="main" class="entry-about"><header class="entry-about-nav"><a class="entry-brand" href="#welcome" aria-label="Candex home">${candexWordmark()}</a><button class="button secondary" data-entry-action="back">${icon('arrow')}Back to demo sign-in</button></header>${platformView()}</main>`;
 return window.CandexLanding?.view({wordmark:candexWordmark(),icon,role:entryRole,language:i18n.lang})||'<main id="main"><h1 id="page-title" tabindex="-1">Candex demo sign-in</h1><p>The entry page could not load. Refresh the page to try again.</p></main>';
}
function navigate(route){if(location.hash===`#${route}`){getRoute();render(true);}else location.hash=route;}
