 if(state.view==='reports'&&state.role==='care'&&window.CandexReferrals)disposeReferrals=window.CandexReferrals.mountReportReview($('#report-review-workspace'),{getDraft:()=>{const d=Object.fromEntries(new FormData($('#report-form')));state.report={...d};return d;},onChange:()=>toast('Demo care journey updated on this browser.')});
 if($('#regional-map-workspace')&&window.CandexRegionalMap)disposeMap=window.CandexRegionalMap.mount($('#regional-map-workspace'));
 if(state.view==='dicom'&&state.role==='care'){import('./dicom.js').then(module=>{dicomModule=module;if(revision===viewRevision&&!entryOpen&&state.role==='care'&&state.view==='dicom')disposeDicom=module.mountDicomPanel($('#dicom-workspace'));else if(entryOpen)module.resetDicomSession?.();}).catch(()=>{if(revision===viewRevision&&!entryOpen&&$('#dicom-workspace'))$('#dicom-workspace').innerHTML='<div class="notice" role="alert">The DICOM Dashboard could not load. Start Candex with python -m backend and open http://localhost:8000, then refresh.</div>';});}

