const stageStatus={done:'Completed',current:'In progress',upcoming:'Upcoming'};
// Live pathway from the demo workflow (care-journey.js); the static list is a fallback.
function stagesNow(){try{return window.CandexJourney?window.CandexJourney.stages():staticPathwayStages;}catch{return staticPathwayStages;}}
const currentStage=(st=stagesNow())=>{const c=st.findIndex(s=>s.status==='current');if(c>=0)return c;let d=0;st.forEach((s,i)=>{if(s.status==='done')d=i;});return d;};
// The patient portal follows the latest health check submitted in this browser (else Aino).
function portalSelect(){try{const p=window.CandexJourney?.portalPatient();if(p)window.CandexReferralStore?.select(p);}catch{}}
function portalName(){try{return window.CandexJourney?.portalPatient().name||'Aino Lehtinen';}catch{return 'Aino Lehtinen';}}
function portalInitials(){return portalName().split(/\s+/).map(w=>w[0]||'').join('').slice(0,2).toUpperCase()||'AL';}
function portalAppointment(){try{portalSelect();return window.CandexReferralStore?.get()?.activeAppointment||null;}catch{return null;}}
function journey(){const pathwayStages=stagesNow();const c=currentStage();return `<div class="journey" aria-label="Care pathway: step ${c+1} of ${pathwayStages.length}, ${pathwayStages[c].title}">${pathwayStages.map((s,i)=>`<div class="journey-step ${s.status==='upcoming'?'':s.status}"><span class="step-circle">${s.status==='done'?icon('check'):i+1}</span><strong>${s.short}</strong><span>${s.status==='current'?'You are here':s.shortDate}</span></div>`).join('')}</div>`;}
function pathwayView(){const pathwayStages=stagesNow();const c=currentStage();const now=pathwayStages[c],next=pathwayStages[c+1];return `${heading('Know what comes next.','Every step of your care, from screening to treatment, with a person responsible at each one.','Your care pathway')}${demoNotice()}<section class="card pathway-summary"><div class="card-head"><h2>Your pathway at a glance</h2><div class="head-actions">${badge(`Step ${c+1} of ${pathwayStages.length}`)}${pathwayInfoButton()}</div></div>${journey()}<div class="pathway-now"><div><small>Now</small><strong>${now.title}</strong><span>${now.date}</span></div><div><small>Next</small><strong>${next?next.title:'Ongoing support'}</strong><span>${next?next.date:''}</span></div><div><small>Your contact</small><strong>Elina Lahti</strong><span>Cancer care nurse · Example team</span></div></div></section><div class="two-col"><section class="card"><div class="card-head"><h2>Step by step</h2>${badge('Lung care example')}</div><ol class="timeline stage-list">${pathwayStages.map((s,i)=>`<li class="timeline-entry stage ${s.status}"><span class="step-circle">${s.status==='done'?icon('check'):icon(s.icon)}</span><div class="stage-body"><div class="stage-top"><small>${i+1} · ${s.date}</small>${badge(stageStatus[s.status],s.status==='current'?'amber':s.status==='upcoming'?'neutral':'')}</div><h3>${s.title}</h3><p>${s.text}</p><div class="stage-details">${s.details.map(([k,v])=>`<div class="data-line"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="journey-note">${icon('info')}<p>${s.means}</p></div>${s.action?`<button class="text-btn space-top" data-action="${s.action[0]}">${s.action[1]}${icon('arrow')}</button>`:''}</div></li>`).join('')}</ol></section><aside class="stack"><section class="card"><div class="card-head"><h2>Your care coordinator</h2>${icon('heart')}</div><div class="patient-mini"><span class="avatar">EL</span><div><h3>Elina Lahti</h3><p style="font-size:.73rem">Cancer care nurse · Example team</p></div></div><p class="subhead" style="font-size:.77rem;margin-bottom:16px">A named point of contact to help you understand your pathway and find the support you need.</p>${goButton('messages','Prepare a message')}</section><section class="card"><div class="card-head"><h2>Key dates</h2>${icon('calendar')}</div>${(()=>{const kd=window.CandexJourney?.keyDates()||[];return kd.length?kd.map(([d,t,st])=>`<div class="data-line key-date ${st}"><span>${d}</span><strong>${t}</strong></div>`).join(''):'<p class="subhead">Your key dates appear here as your care moves forward.</p>';})()}<button class="text-btn space-top" data-action="prep">Prepare for your appointment${icon('arrow')}</button></section><div class="info-panel"><h3>Distance shouldn’t decide your care.</h3><p>Video and phone appointments, travel support needs and clear follow-up reminders are built into the concept.</p><button class="text-btn space-top" data-action="access-support">Explore access support${icon('arrow')}</button></div></aside></div>`;}
